/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";

import PageShell from "@vibaar/ui/PageShell";
import Header from "@/design-system/common/Header";
import Tabs from "@vibaar/ui/common/Tabs";
import VendorNav from "@/features/storefront/VendorNav";
import ChatList from "@/features/chat/ChatList";
import { useRouter } from "next/navigation";
import Assets from "./assets";
import Sort from "./sort";
import useAuthStore from "@/store/authStore";
import Button from "@vibaar/ui/common/Button";

export default function Inbox() {
  const router = useRouter();
  const { user } = useAuthStore();
  // Alerts = notifications (a separate system, still placeholder). Messages =
  // real conversations via the shared ChatList.
  const alertData = [1, 2, 3, 4, 5];

  const alertsTab = (
    <div className="flex flex-col gap-4 pt-2">
      <Sort
        onFilterChange={() => {}}
        searchValue={""}
        onSearchChange={() => {}}
        onSortToggle={() => {}}
      />
      {alertData.length <= 0 ? (
        <AlertMessage />
      ) : (
        alertData.map((it) => <Assets key={it} />)
      )}
    </div>
  );

  const messagesTab = (
    <ChatList onSelect={(c) => router.push(`/inbox/message/${c.id}`)} />
  );

  return (
    <PageShell
      header={
        <Header showBack customText="Inbox" onBackClick={() => router.back()} />
      }>
      {!user ? (
        <div className="flex flex-col items-center justify-center px-8 py-16 text-center">
          <EmptyMessage />
          <p className="text-sm font-medium text-foreground-secondary mt-4">
            Sign in to see your inbox
          </p>
          <p className="text-foreground-muted text-caption mt-2 w-[80%]">
            Your alerts and messages appear here once you sign in.
          </p>
          <div className="mt-6 w-full max-w-[220px]">
            <Button onClick={() => router.push("/signin")}>Sign in</Button>
          </div>
        </div>
      ) : (
        <>
          <Tabs
            tabs={["Alerts", "Messages"]}
            tabContents={[alertsTab, messagesTab]}
          />
          <VendorNav />
        </>
      )}
    </PageShell>
  );
}

